DELETE FROM clinlims.eqa_cycle_state_transition WHERE trigger_event = 'PANEL_RECEIPT';
ALTER TABLE clinlims.eqa_cycle_state_transition DROP CONSTRAINT eqa_cycle_state_transition_trigger_event_chk;
ALTER TABLE clinlims.eqa_cycle_state_transition ADD CONSTRAINT eqa_cycle_state_transition_trigger_event_chk CHECK (trigger_event IN ('LAST_VALIDATED_RESULT', 'FHIR_SUBMIT_SUCCESS', 'FHIR_SUBMIT_FAILURE_RETRY', 'SCORE_INTAKE', 'DEADLINE_TIMER', 'ALL_SHIPMENTS_DELIVERED', 'ALL_SUBMISSIONS_RECEIVED', 'PANEL_SEAL', 'PANEL_UNBLIND', 'HOMOGENEITY_QC_PASSED', 'MANUAL_OVERRIDE', 'SCHEDULED_JOB'))
